        /// <summary>The opcode table for a game version (index = opcode id).</summary>
        public static WazaSeqOp[] Table(WazaSeqVersion v) => v switch
        {
            WazaSeqVersion.DP => Dp,
            WazaSeqVersion.HGSS => Hgss,
            _ => Plat,
        };

        public static int Count(WazaSeqVersion v) => Table(v).Length;

        /// <summary>Fixed argument-word count for an opcode id, or -1 if the id is out of range for the version.</summary>
        public static int ArgCount(WazaSeqVersion v, int id)
        {
            var t = Table(v);
            return (id >= 0 && id < t.Length) ? t[id].ArgCount : -1;
        }

        /// <summary>Symbolic name for an opcode id, or null if out of range.</summary>
        public static string Name(WazaSeqVersion v, int id)
        {
            var t = Table(v);
            return (id >= 0 && id < t.Length) ? t[id].Name : null;
        }

        /// <summary>Opcode id for a symbolic name, or -1 if the version has no such opcode.</summary>
        public static int Id(WazaSeqVersion v, string name)
        {
            var t = Table(v);
            for (int i = 0; i < t.Length; i++) if (t[i].Name == name) return i;
            return -1;
        }
    }
